import { GoogleGenAI } from "@google/genai";
import { ChatMessage } from "../types";

// Fix: Strictly initialized GoogleGenAI with named parameter using process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
You are the AI Concierge for Koi Sushi & Thai & Bar in Ponte Vedra/Jacksonville.
Your goal is to help users book reservations and answer basic questions about the restaurant.

RESTAURANT INFO:
- Location: 80 Executive Way, Ponte Vedra Beach, FL 32082 (Jacksonville area)
- Cuisine: Fresh Sushi, Traditional Thai, and full Craft Bar.
- Atmosphere: Modern, upscale yet welcoming.

RESERVATION RULES:
1. Max party size is 12 for standard booking. Larger groups must call.
2. We serve Lunch (11:30am-3pm) and Dinner (4:30pm-close).
3. If a user wants to book, ask for: Date, Time, Party Size, and Name.

When you have ALL the information (Date, Time, Party Size, Name), you must finalize the booking.
If asked about the menu, highlight our popular items like Dragon Roll or Pad Thai.
Keep your tone warm, professional, and helpful.
`;

export const getGeminiResponse = async (history: ChatMessage[], userMessage: string) => {
  try {
    const formattedHistory = history.map(msg => ({
      role: msg.role === 'user' ? 'user' : 'model',
      parts: [{ text: msg.text }]
    }));

    // Fix: Used ai.models.generateContent directly with required parameters
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...formattedHistory,
        { role: 'user', parts: [{ text: userMessage }] }
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });

    // Fix: Accessed response.text property directly as per latest SDK guidelines
    return response.text || "I'm sorry, I couldn't process that request right now. Please try again or call us directly.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I'm having a bit of trouble connecting to my brain! Please feel free to give us a call for reservations.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { getGeminiResponse } from '../services/geminiService';
import { ChatMessage } from '../types';
