import React, { useState, useRef, useEffect } from 'react';
import { getGeminiResponse } from '../services/geminiService';
import { ChatMessage } from '../types';
import { ScrollReveal } from './ScrollReveal';

export const ReservationsAI: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: "Welcome to the KOI Concierge. I am here to assist with your reservation. When would you like to join us?", timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: ChatMessage = { role: 'user', text: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const responseText = await getGeminiResponse(messages, input);

    setIsTyping(false);
    setMessages(prev => [...prev, { role: 'model', text: responseText, timestamp: new Date() }]);
  };

  return (
    <section id="reservations" className="py-40 bg-koi-black relative overflow-hidden scroll-mt-24">
      <div className="max-w-7xl mx-auto px-6 lg:px-12">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-24 items-start">

          <div className="lg:col-span-5 pt-12">
            <ScrollReveal>
              <span className="text-koi-gold font-bold tracking-[0.5em] uppercase text-[11px] mb-8 block">Exclusive Bookings</span>
              <h2 className="text-6xl md:text-8xl font-serif font-bold text-white mb-12 leading-tight">Digital <br /><span className="gold-gradient-text italic">Concierge</span></h2>
              <p className="text-white/70 text-xl font-light leading-relaxed mb-16 max-w-md">
                Experience seamless table securement through our AI-integrated assistant. Simply state your desired date, time, and party size.
              </p>
            </ScrollReveal>

            <div className="space-y-16">
              <ScrollReveal delay={2} className="flex items-start space-x-8">
                <div className="text-koi-gold text-3xl pt-1 opacity-80">
                  <i className="fas fa-calendar-check"></i>
                </div>
                <div>
                  <h4 className="text-white font-bold uppercase tracking-[0.3em] text-[11px] mb-3">Instant Confirmation</h4>
                  <p className="text-white/50 text-base font-light leading-relaxed">Your table is synchronized instantly with our floor management system.</p>
                </div>
              </ScrollReveal>
              <ScrollReveal delay={3} className="flex items-start space-x-8">
                <div className="text-koi-gold text-3xl pt-1 opacity-80">
                  <i className="fas fa-concierge-bell"></i>
                </div>
                <div>
                  <h4 className="text-white font-bold uppercase tracking-[0.3em] text-[11px] mb-3">Bespoke Requests</h4>
                  <p className="text-white/50 text-base font-light leading-relaxed">Note any dietary preferences or seating desires directly in the chat.</p>
                </div>
              </ScrollReveal>
            </div>
          </div>

          <div className="lg:col-span-7">
            <ScrollReveal delay={1}>
              <div className="bg-[#111] premium-blur border border-white/10 p-2 md:p-10 lg:p-14 shadow-[0_50px_120px_rgba(0,0,0,0.8)] relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-[2px] bg-gradient-to-r from-koi-gold via-koi-gold/50 to-transparent opacity-50"></div>

                <div className="h-[600px] flex flex-col pt-6">
                  <div className="flex-1 overflow-y-auto mb-12 space-y-10 pr-6 scrollbar-hide" ref={scrollRef}>
                    {messages.map((m, i) => (
                      <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-[85%] ${m.role === 'user' ? 'text-right' : 'text-left'}`}>
                          <span className="text-[10px] uppercase font-bold tracking-[0.4em] text-white/30 mb-3 block">
                            {m.role === 'user' ? 'Guest' : 'Koi Concierge'}
                          </span>
                          <div className={`px-0 py-1 text-base md:text-lg leading-[1.8] ${m.role === 'user' ? 'text-koi-gold font-semibold' : 'text-white/90 font-light'}`}>
                            {m.text}
                          </div>
                          <div className={`h-[1px] bg-white/10 mt-6 inline-block ${m.role === 'user' ? 'w-24 bg-koi-gold/30' : 'w-16'}`}></div>
                        </div>
                      </div>
                    ))}
                    {isTyping && (
                      <div className="flex justify-start">
                        <div className="flex space-x-3 py-6">
                          <div className="w-1.5 h-1.5 bg-koi-gold rounded-full animate-bounce"></div>
                          <div className="w-1.5 h-1.5 bg-koi-gold rounded-full animate-bounce [animation-delay:0.2s]"></div>
                          <div className="w-1.5 h-1.5 bg-koi-gold rounded-full animate-bounce [animation-delay:0.4s]"></div>
                        </div>
                      </div>
                    )}
                  </div>

                  <div className="border-t border-white/10 pt-10 pb-6">
                    <div className="relative group">
                      <input 
                        type="text" 
